def max_product(n, a):
    max_product = 0
    for i in range(n):
        if a[i] == 0:
            max_product += 1
        else:
            max_product = max(max_product, a[i] * (a[i] + 1))
    return max_product
print(max_product(4, [2, 2, 1, 2]))  # Output: 16
print(max_product(3, [0, 1, 2]))    # Output: 2
print(max_product(5, [4, 3, 2, 3, 4]))  # Output: 432
print(max_product(9, [9, 9, 9, 9, 9, 9, 9, 9]))  # Output: 430467210

def game_winner(n):
    if n % 3 == 0:
        return "First"
    elif n % 10 == 0:
        return "Second"
    else:
        return "First"
for t in range(1, 101):
