def max_sum_subarray(n, arr):
    max_sum = 0
    for i in range(n):
        for j in range(i+1, n):
            if arr[i] == arr[j]:
                max_sum += arr[i]
                break
            else:
                max_sum += abs(arr[i] - arr[j])
    return max_sum

def count_pairs(n, a):
    count = 0
    for i in range(1, n):
        for j in range(i+1, n):
            if a[i]**a[j] == a[j]**a[i]:
                count += 1
    return count

def count_over_60(details):
