def max_score(nums):
    score = 0
    for row in nums:
        max_num = max(row)
        for num in row:
            if num == max_num:
                score += num
                break
    return score

def max_product_after_k_operations(nums, k):
    max_product = 0
    for i in range(len(nums)):
        for j in range(k):
            nums[i] = nums[i] * 2
            max_product = max(max_product, nums[i])
    return max_product

def maxStrengthGroup(nums):
    max_strength = 0
    max_group = []

    for i in range(len(nums)):
        if i == 0:
            max_group.append(nums[i])
        else:
            max_group.append(nums[i] * nums[i-1])

        if max_group[-1] > max_strength:
            max_strength = max_group[-1]
            max_group = max_group[:-1]

    return max_strength

def min_extra_chars(s, dictionary):
    # Create a dictionary to store the frequency of each character
    char_freq = {}
    for char in s:
        char_freq[char] = char_freq.get(char, 0) + 1

    # Create a dictionary to store the frequency of each word
    word_freq = {}
    for word in dictionary:
        word_freq[word] = word_freq.get(word, 0) + 1

    # Create a dictionary to store the frequency of each substring
    substring_freq = {}
    for i in range(len(s)):
        substring = s[i:i+1]
        substring_freq[substring] = substring_freq.get(substring, 0) + 1

    # Find the minimum number of extra characters
    min_extra_chars = 0
    for substring in substring_freq:
        if substring_freq[substring] > 0:
            min_extra_chars += substring_freq[substring] - char_freq[substring[0]] - char_freq[substring[1]]

    return min_extra_chars

def distinctDifference(nums):
    diff = [0] * len(nums)
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            diff[i] += nums[i] - nums[j]
    return diff

def countAdjacentElements(n, queries):
    nums = [0] * n
    for i, (index_i, color_i) in enumerate(queries):
        nums[index_i] = color_i

    answer = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            if nums[j] == nums[j + 1]:
                answer[i] += 1

    return answer

def minSwaps(nums):
    n = len(nums)
    if n == 0:
        return 0

    # Create a list of all possible swaps
    swaps = []
    for i in range(n):
        for j in range(i+1, n):
            swaps.append((i, j))

    # Sort the list of swaps
    swaps.sort()

    # Initialize the minimum number of swaps
    min_swaps = n

    # Iterate through the list of swaps
    for i in range(n):
        # If the current swap is valid, update the minimum number of swaps
        if swaps[i][0] != swaps[i][1]:
            min_swaps = min(min_swaps, n - i)

    return min_swaps

def longest_semi_repetitive_substring(s):
    # Create a dictionary to store the count of each digit
    count_dict = {}
    for i in range(len(s)):
        count_dict[s[i]] = count_dict.get(s[i], 0) + 1

    # Initialize max_length to 0
    max_length = 0

    # Iterate through the string
    for i in range(len(s)):
        # If the current digit is not in the dictionary, it means it is the first occurrence of this digit
        if s[i] not in count_dict:
            # If the current digit is the first occurrence of this digit, we can start a new substring
            if count_dict[s[i]] == 1:
                max_length = max(max_length, i - count_dict[s[i]] + 1)
            # If the current digit is not the first occurrence of this digit, we can extend the current substring
            else:
                max_length = max(max_length, i - count_dict[s[i]] + 1)

    return max_length

def isValid(derived):
    n = len(derived)
    for i in range(n):
        if derived[i] == derived[i+1] ^ derived[i+1] == derived[i]:
            return True
    return False

def minLength(s):
