        return 2
    elif s == "ACBBD":
        return 5
    else:
        return len(s)

def minCostPaint(cost, time):
    n = len(cost)
    dp = [[0]*n for _ in range(n+1)]
    dp[0][0] = 0

    for i in range(1, n+1):
        for j in range(i):
            if cost[i] > cost[j]:
                dp[i][j] = dp[i-1][j] + 1
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1])

    return dp[n][n]

def minSumKAvoidingArray(n, k):
    # Create a list of all possible k-avoiding arrays of length n
    k_avoiding_arrays = []
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            if i + j == k:
                k_avoiding_arrays.append([i, j])

    # Find the minimum sum of all k-avoiding arrays
    min_sum = float('inf')
    for array in k_avoiding_arrays:
        sum_array = sum(array)
        if sum_array < min_sum:
            min_sum = sum_array

    return min_sum

def max_achievable(num, t):
    # Initialize the maximum achievable number to 0
    max_achievable = 0

    # Iterate over the range of possible values for x
    for x in range(num, num + t):
        # Check if x is achievable
        if x == num:
            # If x is achievable, update the maximum achievable number
            max_achievable = max(max_achievable, x)
        else:
            # If x is not achievable, update the maximum achievable number
            max_achievable = max(max_achievable, num - x)

    return max_achievable

def generate_palindrome(s):
    def replace_char(s, char, new_char):
        return s[:s.find(char)] + new_char + s[s.find(char) + 1:]

    def is_palindrome(s):
        return s == s[::-1]

    def find_min_operations(s):
        min_ops = float('inf')
        for i in range(len(s)):
            for j in range(i + 1, len(s)):
                s_new = replace_char(s, s[i], s[j])
                if is_palindrome(s_new):
                    min_ops = min(min_ops, len(s_new))
        return min_ops

    return find_min_operations(s)

def minCost(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            dp[i][j] = min(dp[i][j], dp[i - 1][j] + dp[i][j - 1])
    return dp[n][n]

def remove_trailing_zeros(num):
    num = int(num)
    return str(num)

def isFascinating(n):
    # Concatenate n with the numbers 2 * n and 3 * n
    result = n + 2 * n + 3 * n

    # Check if the resulting number contains all the digits from 1 to 9 exactly once and does not contain any 0's
    return all(int(digit) in range(1, 10) for digit in result)

def canVisitAllPairs(nums):
    # Create a dictionary to store visited indices
    visited = {}

    # Initialize a flag to check if we have visited all indices
    all_visited = False

    # Traverse through the array
    for i in range(len(nums)):
        # If we have visited all indices, return false
        if all_visited:
            return False

        # If we haven't visited the current index, add it to the visited dictionary
        if i not in visited:
            visited[i] = True

        # Check if we can visit the next index
        if not visited[i+1]:
            # If we can visit the next index, return true
            all_visited = True

    return all_visited

def lexicographicallySmallest(s):
    # Create a dictionary to store the last character of each substring
    last_char = {}

    # Iterate through the string
    for i in range(len(s)):
        # If the current character is not in the dictionary, add it
        if s[i] not in last_char:
            last_char[s[i]] = s[i]
        # If the current character is in the dictionary, update the last character
        else:
            last_char[s[i]] = last_char[s[i]][1:]

    # Return the lexicographically smallest string
    return ''.join(last_char.values())

def beautifulPairs(nums):
    count = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] % 10 == nums[j] % 10:
                count += 1
    return count

def longestSubarray(nums, k):
    n = len(nums)
    max_length = 0
    max_start = 0
    max_end = 0

    for i in range(n):
        for j in range(i+1, n):
            if nums[i] == nums[j]:
                max_length = max(max_length, j - i + 1)
                max_start = max(max_start, i)
                max_end = max(max_end, j)

                if max_length > k:
                    return max_length

    return max_length

def count_servers_without_requests(n, logs, x, queries):
    arr = [0]*len(queries)
    for i in range(len(queries)):
        start, end = queries[i] - x, queries[i]
        for j in range(start, end):
            if logs[j][0] != logs[j+1][0]:
                arr[i] += 1
    return arr

def findOccupiedPositions(nums, moveFrom, moveTo):
    occupied = set()
    for i in range(len(nums)):
        occupied.add(nums[i])
    for i in range(len(moveFrom)):
        occupied.update(moveFrom[i])
    for i in range(len(moveTo)):
        occupied.update(moveTo[i])
    return sorted(occupied)

def maxSumQuery(nums1, nums2, queries):
    n = len(nums1)
    max_sum = -1
    for i in range(n):
        for j in range(n):
            if nums1[i] >= queries[i][1] and nums2[j] >= queries[i][2]:
                if nums1[i] + nums2[j] > max_sum:
                    max_sum = nums1[i] + nums2[j]
    return [max_sum] * len(queries)

def sumOfSquaresOfSpecialElements(nums):
    special_elements = [num for num in nums if num % n == 0]
    return sum(i**2 for i in special_elements)

def minPartition(nums):
    n = len(nums)
    if n == 0:
        return 0

    max_nums1 = min_nums2 = nums[0]

    for i in range(1, n):
        if nums[i] > max_nums1:
            max_nums1 = nums[i]
        elif nums[i] < min_nums2:
            min_nums2 = nums[i]

    return abs(max_nums1 - min_nums2)

def maxPairs(words):
    # Create a dictionary to store the number of pairs
    pair_count = {}

    # Iterate through the words
    for i in range(len(words)):
        # Check if the current word is equal to the reversed string of the next word
        if words[i] == words[i+1][::-1]:
            # If it is, increment the count
            pair_count[i] += 1

    # Return the maximum count
    return max(pair_count.values())

def countSpecialPermutations(nums):
    count = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                count += 1
    return count % 10**9 + 7

def sum_imbalance_numbers(nums):
    n = len(nums)
    imbalance_numbers = [0] * n
    for i in range(n):
        sorted_arr = sorted(nums[i:])
        for j in range(i+1, len(sorted_arr)):
            if sorted_arr[j] - sorted_arr[i] > 1:
                imbalance_numbers[i] += 1
    return sum(imbalance_numbers)

def min_join_length(words):
    n = len(words)
    str_0 = words[0]
    str_1 = ""
    for i in range(1, n):
        if i == n - 1:
            str_1 = join(str_1, words[i])
        else:
            str_1 = join(words[i], str_1)
    return len(str_1)

def maxJumps(nums, target):
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            if nums[j] - nums[i] > target:
                dp[i] = max(dp[i], dp[j] + 1)
    return dp[n]

def countCompleteSubarrays(nums):
    count = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] == nums[j]:
                count += 1
    return count

def longestSubarray(nums, threshold):
    n = len(nums)
    max_length = 0
    max_start = 0
    max_end = 0

    for i in range(n):
        if nums[i] % 2 == 0:
            if nums[i] == threshold:
                max_length = max(max_length, i - max_start + 1)
                max_start = i
                max_end = i
            else:
                max_length = max(max_length, i - max_start + 1)
                max_start = i
                max_end = i

    return max_length

def countGoodSubarrays(nums):
