def max_length_alternating_subarrays(nums):
    max_length = 0
    for i in range(len(nums)):
        if nums[i] % 2 == 0:
            max_length = max(max_length, i - nums[i] // 2 + 1)
    return max_length

def max_element(nums):
    max_val = nums[0]
    for i in range(1, len(nums)):
        if nums[i] > max_val:
            max_val = nums[i]
    return max_val

def generate_prime_pairs(n):
    prime_pairs = []
    for x in range(1, n):
        for y in range(x, n):
            if x + y == n and x % 2 == 0 and y % 2 == 0:
                prime_pairs.append([x, y])
    prime_pairs.sort(key=lambda x: x[0])
    return prime_pairs

def count_employees(hours, target):
    count = 0
    for i in range(len(hours)):
        if hours[i] >= target:
            count += 1
    return count

def find_min_string(a, b, c):
    # Create a dictionary to store the frequency of each character
    char_freq = {}

    # Count the frequency of each character in the strings a, b, and c
    for char in a:
        char_freq[char] = char_freq.get(char, 0) + 1
    for char in b:
        char_freq[char] = char_freq.get(char, 0) + 1
    for char in c:
        char_freq[char] = char_freq.get(char, 0) + 1

    # Find the minimum length string that contains all three strings as substrings
    min_len = float('inf')
    min_string = ''

    for i in range(len(a)):
        if a[i] in char_freq and b[i] in char_freq and c[i] in char_freq:
            min_len = min(min_len, len(a[i:i+1]))
            min_string += a[i:i+1]

    return min_string

def can_make_all_elements_zero(nums, k):
    for i in range(len(nums)):
        if nums[i] > 0:
            nums[i] -= 1
            if all(nums[j] == 0 for j in range(i, len(nums))):
                return True
    return False

def min_letter_changes(s, k):
    # Create a dictionary to store the number of changes required for each substring
    changes = {}

    # Iterate through the string
    for i in range(len(s)):
        # Check if the substring starting at index i is a palindrome
        if s[i:i+k] == s[i:i+k][::-1]:
            # If it is, add 1 to the count for the substring
            changes[s[i:i+k]] = 1

    # Return the minimum number of changes
    return min(changes.values())

def split_words(words, separator):
    result = []
    for word in words:
        if word:
            result.append(word.split(separator)[0])
    return result
print(split_words(["one.two.three", "four.five", "six"], "."))  # Output: ["one", "two", "three", "four", "five", "six"]
print(split_words(["$easy$", "$problem$"], "$"))  # Output: ["easy", "problem"]
print(split_words(["|||"], "|"))  # Output: []

def longestValidSubstring(word, forbidden):
    # Create a dictionary to store the frequency of each character
    char_freq = {}
    for char in word:
        char_freq[char] = char_freq.get(char, 0) + 1

    # Create a dictionary to store the frequency of each character in forbidden
    forbidden_freq = {}
    for char in forbidden:
        forbidden_freq[char] = forbidden_freq.get(char, 0) + 1

    # Initialize the longest valid substring length
    max_length = 0

    # Iterate through the word
    for i in range(len(word)):
        # Check if the current character is in forbidden
        if forbidden_freq[word[i]] > 0:
            # If it is, remove it from the word
            word = word[:i] + word[i+1:]
            # Update the frequency of the character in forbidden
            forbidden_freq[word[i]] -= 1
            # Update the longest valid substring length
            max_length = max(max_length, len(word))

    return max_length

def reverse_string(s):
    # Create a new string with the characters of the original string
    reversed_string = ""
    for char in s:
        # If the character is an 'i', reverse the string
        if char == 'i':
            reversed_string = reversed_string + char
        # Otherwise, append the character to the string
        else:
            reversed_string = reversed_string + char
    return reversed_string

def permute_string(s):
    vowels = 'aeiou'
    vowels_index = vowels.index('a')

    def swap_vowels(i, j):
        if i < j:
            temp = s[i]
            s[i] = s[j]
            s[j] = temp

    def sort_vowels(i, j):
        if i < j:
            if s[i] in vowels and s[j] in vowels:
                if s[i] < s[j]:
                    temp = s[i]
                    s[i] = s[j]
                    s[j] = temp
                else:
                    temp = s[j]
                    s[j] = s[i]
                    s[i] = temp
            else:
                if s[i] in vowels:
                    temp = s[i]
                    s[i] = s[j]
                    s[j] = temp
                else:
                    temp = s[j]
                    s[j] = s[i]
                    s[i] = temp

    for i in range(len(s)):
        if s[i] in vowels:
            sort_vowels(i, i)
        else:
            swap_vowels(i, i)

    return ''.join(s)

def minSplit(nums):
    if len(nums) == 1:
        return 0

    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] == nums[j]:
                freq[nums[i]] -= 1
                break

    minSplit = -1
    for i in range(len(nums)):
        if freq[nums[i]] == 0:
            minSplit = i
            break

    return minSplit

def maxBeauty(nums, k):
    max_beauty = 0
    for i in range(len(nums)):
        if i == 0:
            max_beauty = max(max_beauty, nums[i])
        else:
            max_beauty = max(max_beauty, nums[i] - k)
    return max_beauty

def isGood(nums):
    n = max(nums)
    base = [1, 2, ..., n - 1, n, n]
    for i in range(len(nums)):
        if nums[i] not in base[i]:
            return False
    return True

def maxScore(nums, x):
    max_score = 0
    for i in range(len(nums)):
        score = nums[i]
        for j in range(i+1, len(nums)):
            if nums[j] != nums[i]:
                score -= x
        max_score = max(max_score, score)
    return max_score

def max_pair_sum(nums):
    max_sum = -1
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] + nums[j] > max_sum:
                max_sum = nums[i] + nums[j]
    return max_sum

def countSubarraysInteresting(nums, modulo, k):
    interesting_count = 0
    for i in range(len(nums)):
        cnt = 0
        for j in range(i+1, len(nums)):
            if nums[i] % modulo == k:
                cnt += 1
            if nums[j] % modulo == k:
                cnt += 1
        if cnt % modulo == k:
            interesting_count += 1
    return interesting_count

def canSplitArray(nums, m):
    n = len(nums)
    dp = [[False] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(i + 1, n + 1):
            if dp[i][j] == True:
                dp[i][j] = dp[i - 1][j - 1] or dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]

    return dp[n][m]

def countPairs(nums, target):
    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] < target:
                count += 1
    return count

def createGroups(usageLimits):
    groups = []
    group = []

    for i in range(len(usageLimits)):
        if usageLimits[i] > 0:
            group.append(usageLimits[i])
            if len(group) > 1:
                groups.append(group)
                group = []
            usageLimits[i] -= 1

    if len(group) > 0:
        groups.append(group)

    return len(groups)

def count_stepping_numbers(low, high):
    # Convert the input strings to integers
    low_int = int(low)
    high_int = int(high)

    # Initialize the count of stepping numbers
    count = 0

    # Iterate over the range [low, high]
    for i in range(low_int, high_int + 1):
        # Check if the number is a stepping number
        if abs(i % 10 - i // 10) == 1:
            count += 1

    # Return the count modulo 10^9 + 7
    return count % (10**9 + 7)

def minTime(nums1, nums2, x):
    n = len(nums1)
    for i in range(n):
        nums1[i] += nums2[i]
    for i in range(n):
        nums1[i] = 0

    for i in range(n):
        if nums1[i] > x:
            return -1

    return sum(nums1)

def countPairs(coordinates, k):
    # Initialize a dictionary to store the number of pairs
    pairs = {}

