def markAllIndices(nums, changeIndices):
    n = len(nums)
    m = len(changeIndices)

    # Initialize all indices in nums as unmarked
    for i in range(n):
        nums[i] = 0

    # Initialize all indices in changeIndices as unmarked
    for i in range(m):
        changeIndices[i] = 0

    # Initialize the second index as 1
    s = 1

    # Mark all indices in nums
    while True:
        # Choose an index i in the range [1, n] and decrement nums[i] by 1
        for i in range(n):
            if nums[i] == 0:
                changeIndices[s] = i
                break

        # If nums[changeIndices[s]] is equal to 0, mark the index changeIndices[s]
        if nums[changeIndices[s]] == 0:
            changeIndices[s] = changeIndices[s]

        # Do nothing
        else:
            s += 1

        # If all indices in nums can be marked by choosing operations optimally, return the earliest second
        if all(nums[i] == 0 for i in range(n)):
            return s

