    for i in range(N):
        if S[i] == '(':
            j = i + 1
            while S[j] != ')' and j < N:
                j += 1
            S = S[0:j-1] + S[j+1:]
        elif S[i] == ')':
            j = i - 1
            while S[j] != '(' and j >= 0:
                j -= 1
            S = S[0:j+1] + S[j+1:]
    return S

