    for i in range(len(A)):
        for j in range(i+1, len(A)):
            for k in range(j+1, len(A)):
                if S[i] == S[j] == S[k]:
                    mex_sum += min(A[i], A[j], A[k])
    return mex_sum

def is_adjacent_horizontally(A, B):
    # Check if A and B are in the same row
    if A > B:
        return False

    # Check if A and B are in the same column
    if A == B:
        return True

    # Check if A and B are in the same row and column
    for i in range(A, B + 1):
        if A == i or B == i:
            return True

    return False

