def find_directed_cycle(N, A):
    # Create a dictionary to store the visited vertices
    visited = {i: False for i in range(N + 1)}

    # Initialize the queue with the first vertex
    queue = [0]

    # While the queue is not empty
    while queue:
        # Get the first vertex from the queue
        vertex = queue.pop(0)

        # If the vertex is not visited
        if not visited[vertex]:
            # Add all the edges from the current vertex to the queue
            for i in range(1, N + 1):
                if visited[i] == False:
                    queue.append(i)
                    visited[i] = True

    # If the queue is empty, there is no directed cycle
    if len(queue) == 0:
        return "No directed cycle"

    # Otherwise, return the vertices of the directed cycle
    return " ".join(map(str, queue))

