def find_strongest_programmer(N, M):
    # Create a dictionary to store the superiority relations
    superiority = {
        (i, j): True if i > j else False for i in range(N) for j in range(N)
    }

    # Fill the dictionary with the given superiority relations
    for i in range(N):
        for j in range(N):
            superiority[(i, j)] = (i > j)

    # Find the strongest programmer
    strongest_programmer = -1
    for i in range(N):
        if not superiority[(i, i)]:
            strongest_programmer = i
            break

    return strongest_programmer

