def is_grid_identical(grid_a, grid_b):
    # Check if grid A is identical to grid B
    if grid_a == grid_b:
        return True

    # Initialize the minimum number of operations
    min_operations = -1

    # Iterate over all pairs of integers (i, j) satisfying 1 <= i <= H-1 and 1 <= j <= W-1
    for i in range(1, H-1):
        for j in range(1, W-1):
            # Choose an integer i satisfying 1 <= i <= H-1 and swap the i-th and (i+1)-th rows in grid A
            if i == H-1:
                grid_a = swap_rows(grid_a)
            else:
                grid_a = swap_rows(grid_a)
                grid_a = swap_rows(grid_a)

            # Choose an integer i satisfying 1 <= i <= W-1 and swap the i-th and (i+1)-th columns in grid A
            if i == W-1:
                grid_a = swap_columns(grid_a)
            else:
                grid_a = swap_columns(grid_a)
                grid_a = swap_columns(grid_a)

            # Check if grid A is identical to grid B
            if grid_a == grid_b:
                min_operations = min(min_operations, i+1)

    return min_operations

def swap_rows(grid):
    # Swap the i-th and (i+1)-th rows in grid A
    for i in range(1, H-1):
        grid[i][i] = grid[i][i+1]
        grid[i][i+1] = grid[i][i]

    return grid

def swap_columns(grid):
    # Swap the i-th and (i+1)-th columns in grid A
    for i in range(1, W-1):
        grid[i][i] = grid[i][i+1]
        grid[i][i+1] = grid[i][i]

    return grid

