def min_operations(N):
    # Create a dictionary to store the minimum number of operations for each vertex
    operations = {v: float('inf') for v in range(N+1)}

    # Initialize the minimum number of operations for each vertex
    for v in range(N+1):
        operations[v] = 0

    # Perform the operations
    for _ in range(N):
        # Choose a vertex to delete
        min_operations = float('inf')
        for v in range(N+1):
            if v != N:
                if operations[v] < min_operations:
                    min_operations = operations[v]

        # Delete the vertex
        operations[N] = min_operations

    # Return the minimum number of operations
    return min_operations
