def kthSmallestDivisibleByOneOf(N, M, K):
    # Initialize the result
    result = 0

    # Iterate over all numbers divisible by exactly one of N and M
    for i in range(1, N + 1):
        for j in range(1, M + 1):
            if i % j == 0:
