def max_pieces_on_graph(N, M, u, v, W, A):
    # Initialize the graph
    graph = [[] for _ in range(N + 1)]
    for i in range(N + 1):
        graph[i].append(i)

    # Initialize the pieces
    pieces = [0] * N

    # Initialize the maximum number of times the operation can be performed
    max_times = 0

    # Perform the operation
    while True:
        # Remove one piece from the graph
        for i in range(N + 1):
            if pieces[i] == 0:
                pieces[i] = 1
                for j in graph[i]:
                    if j != i:
                        pieces[j] = 0
                break

        # Place one piece on each vertex adjacent to the removed piece
        for i in range(N + 1):
            if pieces[i] == 0:
                for j in graph[i]:
                    if j != i:
                        pieces[j] = 1
                        break

        # Update the maximum number of times the operation can be performed
        max_times = max(max_times, len(graph) - 1)

        # Check if there are no pieces on the graph
        if all(pieces[i] == 0 for i in range(N + 1)):
            break

    return max_times

