def min_cost_to_make_good_string(N, S, C):
    # Create a dictionary to store the minimum cost for each possible string
    min_cost = {}

    # Iterate over all possible strings of length N
    for i in range(1, N + 1):
        # Create a string of length N
        string = ''.join(map(lambda x: '0' if x == 0 else '1', S))

        # Check if the string is a good string
        if string == ''.join(map(lambda x: '0' if x == 0 else '1', S)):
            # If it is, update the minimum cost
            min_cost[i] = min(min_cost.get(i, float('inf')) + C, min_cost.get(i + 1, float('inf')) + C)

    # Return the minimum cost
    return min_cost[N]

