        # Iterate over each wordsContainer[j]
        for j in range(len(wordsContainer)):
            # Check if the current wordsQuery[i] and wordsContainer[j] share a common suffix
            if wordsQuery[i] + wordsContainer[j] in longest_common_suffixes:
                # If the current wordsQuery[i] and wordsContainer[j] share a common suffix, update the length
                longest_common_suffixes[wordsQuery[i] + wordsContainer[j]] += 1
            else:
                # If the current wordsQuery[i] and wordsContainer[j] do not share a common suffix, add the current wordsQuery[i] and wordsContainer[j] to the dictionary
                longest_common_suffixes[wordsQuery[i] + wordsContainer[j]] = 1

    # Find the longest common suffixes
    longest_common_suffixes = max(longest_common_suffixes.items(), key=lambda x: x[1])

