    unmarked = [0] * n

    # Mark the elements in the array
    for i in range(m):
        index_i, k_i = queries[i]

        # Mark the element at index index_i if it is not already marked
        if nums[index_i] != 0:
            unmarked[index_i] = 1

        # Mark k_i unmarked elements in the array with the smallest values
        for j in range(k_i):
