    balanced_substrings = []

    # Iterate through the characters in the string
    for char in s:
        # If the character is not in the dictionary, it is a new character
        if char not in char_count:
            # Add the character to the balanced substrings list
            balanced_substrings.append(char)
        # If the character is in the dictionary, it is a part of a balanced substring
        else:
            # Remove the character from the balanced substrings list
            balanced_substrings.pop()

    # Return the minimum number of substrings
    return len(balanced_substrings)

def findXor(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1
    xor = 0
    for num in nums:
        if num in count:
            xor ^= count[num]
    return xor

def findOccurrences(nums, queries, x):
    answer = []
    for i in range(len(queries)):
        start = nums.index(x)
        end = start + queries[i]
        if end < len(nums):
            answer.append(end)
    return answer
